WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_data_analysis_elimination'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '排除分析', 'kp-xingce-data-analysis-elimination', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "排除分析（无法推出题型）"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "综合分析中的送分怪，专门考察定性不可推定量、材料边界感。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目问：“根据以上资料，能够推出/不能推出的是？”。尤其是“无法推出”，考的是严谨的逻辑边界。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、三种必死模型（无中生有）"}]}, {"type": "bulletList", "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "只给率，硬算量：材料全是百分比（折线图），没给总基数。选项硬说“总额超过100亿”。神仙也算不出绝对量，直接判死！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "部分强推整体：材料只给了“规上工业企业”数据。选项说“全部工业总产值如何”。规上不代表全部，直接判死！"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "时间轴穿越：材料只给了2018-2023年的数据。选项硬说“2017年增长了...”。没有历史基数，直接判死！"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[阅读选项] --> B[检查选项里的'时间'、'主体'、'单位'是否在材料中存在]\nB --> C{出现了材料没有的要素?}\nC -- 出现了历史/未来时间 --> D[缺乏基期/预测数据, 无法推出!]\nC -- 出现了未定义的母集/子集 --> E[偷换概念, 无法推出!]\nC -- 全是相对率却问绝对值 --> F[只知变化不知盘子, 无法推出!]\nD --> G[秒选出无法推出的选项]\nE --> G\nF --> G"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题完整推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 资料只有图：2023年某地市三大产业各自的同比增长率折线图（一产2%，二产5%，三产8%）。选出无法推出的一项？选项：A. 三产增速最高。 B. 二产增速比一产快。 C. 该市2023年总体GDP保持正增长。"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 A和B：直接比较折线的高低，显然成立。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看 C：材料只给了三个部分的增长率，没有给这三个部分在总盘子中的绝对量或比重！因为不知道各个产业体量有多大，就无法计算加权混合后的整体 GDP 增速。就算它们三个都是正的，这只是特例；如果有跌有涨，没有权重绝对算不出整体。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "更致命的：如果是全部正增长，整体必然正增长（混合必在之间），但如果选项给了具体数值就无法推了！本题中C确实能推（全正必正），但如果有选项问“整体增速超过5%”，那就绝对无法推出了。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "常识脑补综合症：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "选项写：“第一产业比重连年下降，说明我国农业衰退”。前半句能在数据里查到，后半句是常识主观推断。在资料分析里，数据论证是唯一的王道，不带有任何感情色彩。这种定性脑补的选项直接判为“无法推出”！"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "六、刷题建议"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "对于“不能推出”题，放弃计算，切换成“找不同”的侦探模式，专挑选项里那些刺眼的生面孔词汇。"}]}]}$$ AS jsonb), NULL, '排除分析的核心考点与实战推导。', category_node.id, CAST('["资料分析", "排除分析"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_data_analysis_elimination", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
